import sys

MAX_INF = int(1e6)

def solve(idx, pCount, nCount, carryVal):
    trueCarry = carryVal - 50
    if idx == 17:
        if pCount + nCount + trueCarry == 0:
            return 0
        return MAX_INF
    if memoTable[idx][pCount][nCount][carryVal] != -1:
        return memoTable[idx][pCount][nCount][carryVal]
    minRes = MAX_INF
    for p in range(min(15, pCount) + 1):
        for n in range(min(15, nCount) + 1):
            sum_val = pCount - nCount + trueCarry
            digit = (sum_val % 10 + 10) % 10
            nextCarry = (sum_val // 10) if sum_val > 0 else ((sum_val - 9) // 10)
            if digit != int(numStrRev[idx]):
                continue
            res = solve(idx + 1, pCount - p, nCount - n, nextCarry + 50) + (p + n) * (idx + 1)
            if res < minRes:
                minRes = res
    memoTable[idx][pCount][nCount][carryVal] = minRes
    return minRes

def main():
    inputNumber = int(sys.stdin.read().strip())
    sizeLimit = 50
    global memoTable, numStrRev
    memoTable = [[[[-1 for _ in range(100)] for _ in range(sizeLimit)] for _ in range(sizeLimit)] for _ in range(20)]
    numStrRev = str(inputNumber)
    while len(numStrRev) < 17:
        numStrRev = "0" + numStrRev
    numStrRev = numStrRev[::-1]
    minRes = MAX_INF
    for p in range(sizeLimit):
        for n in range(sizeLimit):
            res = solve(0, p, n, 50)
            if res < minRes:
                minRes = res
    print(minRes)

if __name__ == "__main__":
    main()

